/* Cairo governorate emblem: Al-Azhar minarets, a shining sun behind, the word Cairo on the base */
function cairoEmblem(s=1,full=true,parts={sun:1,mosque:1,word:1}){const sun=parts.sun?`<g><g><animateTransform attributeName="transform" type="rotate" values="-4 0 -40;4 0 -40;-4 0 -40" dur="6s" repeatCount="indefinite"/>${[...Array(12)].map((_,i)=>{const a=-Math.PI+i*Math.PI/11;return `<path d="M0 -30 L${(Math.cos(a)*150).toFixed(1)} ${(-30+Math.sin(a)*150).toFixed(1)} L${(Math.cos(a+.12)*150).toFixed(1)} ${(-30+Math.sin(a+.12)*150).toFixed(1)}Z" fill="#facc15"/>`}).join('')}</g><circle cx="0" cy="-40" r="44" fill="#fbbf24"/></g>`:'';
 const mos=parts.mosque?`<g fill="#3730a3"><rect x="-70" y="-110" width="16" height="140"/><path d="M-74 -110 L-62 -138 L-50 -110Z"/><path d="M-62 -146 a5 5 0 1 0 1 0" fill="none" stroke="#3730a3" stroke-width="3"/><rect x="54" y="-110" width="16" height="140"/><path d="M50 -110 L62 -138 L74 -110Z"/><rect x="-8" y="-80" width="16" height="110"/><path d="M-12 -80 L0 -104 L12 -80Z"/><path d="M-50 30 V-10 Q-30 -40 -10 -10 V30Z M10 30 V-10 Q30 -40 50 -10 V30Z"/></g>`:'';
 const word=parts.word?`<g><rect x="-90" y="34" width="180" height="46" fill="#3730a3"/><text x="0" y="68" text-anchor="middle" font-size="30" font-weight="900" fill="#fff" style="font-family:'Baloo Bhaijaan 2'">الْقَاهِرَةُ</text></g>`:'';
 return `<g transform="scale(${s})">${full?'<rect x="-110" y="-170" width="220" height="260" rx="10" fill="#fff" stroke="#3730a3" stroke-width="4"/>':''}${sun}${mos}${word}</g>`}
